// Generated by tools/player-offline.mjs; deliberately enabled only on the
// standalone static WASM player. Never register on Studio or a local backend.
const BUILD=__NEKOC_OFFLINE_BUILD__;
const scope=self.registration.scope;
const prefix=`nekoc-player:${scope}:`;
const runtimeName=`${prefix}runtime:${BUILD.version}`;
const projectName=`${prefix}projects:v1`;
const shell=new Set(BUILD.files.map(file=>new URL(file,scope).href));
const entry=new URL('play.html',scope).href;
const maxProject=64*1024*1024,maxAsset=16*1024*1024,maxLibrary=128*1024*1024,maxWorks=5;
const privateResponse=response=>/\b(?:private|no-store)\b/i.test(response.headers.get('cache-control')||'');
const encoder=new TextEncoder();
let writes=Promise.resolve();

async function runtimeResponse(url){
  const response=await fetch(new Request(url,{credentials:'omit',cache:'reload',referrerPolicy:'no-referrer',signal:AbortSignal.timeout(60000)}));
  if(!response.ok||response.redirected||privateResponse(response))throw Error('Offline runtime download failed');
  const bytes=await response.arrayBuffer();
  const digest=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(byte=>byte.toString(16).padStart(2,'0')).join('');
  if(digest!==BUILD.digests[url.slice(scope.length)])throw Error('Offline runtime version mismatch');
  const headers=new Headers(response.headers);
  // fetch already decoded transfer/content encodings before hashing.
  headers.delete('content-encoding');headers.delete('content-length');
  return new Response(bytes,{headers});
}

self.addEventListener('install',event=>{
  event.waitUntil((async()=>{
    const cache=await caches.open(runtimeName);
    try{
      for(const url of shell){
        await cache.put(url,await runtimeResponse(url));
      }
    }catch(error){await caches.delete(runtimeName);throw error;}
    // Do not skipWaiting: a running player must not mix old JS with new WASM.
  })());
});
self.addEventListener('activate',event=>{
  event.waitUntil((async()=>{
    for(const name of await caches.keys())if(name.startsWith(`${prefix}runtime:`)&&name!==runtimeName)await caches.delete(name);
    // Saved works use a separate schema version and survive runtime updates.
    // Do not claim initially uncontrolled pages: their network-loaded JS may
    // predate this install. The next navigation starts wholly on this version.
  })());
});
self.addEventListener('fetch',event=>{
  const request=event.request,url=new URL(request.url);
  if(request.method!=='GET'||request.headers.has('authorization')||request.headers.has('range'))return;
  // No catch-all runtime caching: APIs, source URLs, credentials, query strings,
  // extension calls and arbitrary navigations never enter Cache Storage.
  const key=request.mode==='navigate'&&url.origin===new URL(scope).origin&&url.pathname===new URL(entry).pathname
    ?entry:!url.search&&shell.has(url.href)?url.href:null;
  if(key)event.respondWith((async()=>{
    const cache=await caches.open(runtimeName),cached=await cache.match(key);
    if(cached)return cached;
    // Browser eviction need not permanently brick the online player. Only
    // identical active-version bytes may repair a missing entry.
    try{
      const response=await runtimeResponse(key);
      try{await cache.put(key,response.clone());}catch{/* Online playback survives a full storage quota. */}
      return response;
    }
    catch{return Response.error();}
  })());
});

function assetURL(source){
  const url=new URL(source,entry);
  if(!['https:','http:'].includes(url.protocol)||url.username||url.password||url.search||url.hash
    ||/\/(?:api|auth|login|logout|account|users?|private)(?:\/|$)/i.test(decodeURIComponent(url.pathname)))
    throw Error('offlineUnsafeAsset');
  return url.href;
}
function checkSVG(text){
  const refs=[...[...text.matchAll(/\bhref\s*=\s*(["'])(.*?)\1/gi)].map(match=>match[2]),
    ...[...text.matchAll(/\burl\(\s*(["']?)(.*?)\1\s*\)/gi)].map(match=>match[2])];
  // Conservative: escapes/entities or active markup can disguise external
  // dependencies. Reject instead of silently claiming these assets are offline.
  if(refs.some(ref=>!/^#/i.test(ref.trim()))||/[\0&@\\]|<\s*(?:script|foreignObject|animate\w*|set|!ENTITY|!DOCTYPE)\b/i.test(text))throw Error('offlineUnsafeAsset');
}
function base64(bytes){
  let text='';
  for(let offset=0;offset<bytes.length;offset+=8192)text+=String.fromCharCode(...bytes.subarray(offset,offset+8192));
  return btoa(text);
}
async function readAsset(source,kind,deadline){
  if(source.startsWith('data:')){
    const comma=source.indexOf(','),header=source.slice(0,comma),mime=header.slice(5).split(';')[0].trim().toLowerCase();
    if(comma<0||!mime.startsWith(`${kind}/`))throw Error('offlineUnsafeAsset');
    if(mime==='image/svg+xml'){
      const body=source.slice(comma+1);
      checkSVG(/;base64$/i.test(header)?atob(body):decodeURIComponent(body));
    }
    return source;
  }
  const url=assetURL(source);
  const response=await fetch(url,{credentials:'omit',mode:'cors',cache:'no-store',referrerPolicy:'no-referrer',redirect:'error',signal:AbortSignal.timeout(Math.max(1,Math.min(60000,deadline-Date.now())))});
  const mime=(response.headers.get('content-type')||'').split(';')[0].trim().toLowerCase();
  if(!response.ok||response.type==='opaque'||privateResponse(response)||!mime.startsWith(`${kind}/`)){
    await response.body?.cancel();throw Error('offlineUnsafeAsset');
  }
  if(Number(response.headers.get('content-length'))>maxAsset){await response.body?.cancel();throw Error('offlineTooLarge');}
  const reader=response.body?.getReader(),chunks=[];let length=0;
  if(!reader)throw Error('offlineUnsafeAsset');
  try{
    for(;;){const {done,value}=await reader.read();if(done)break;length+=value.length;if(length>maxAsset)throw Error('offlineTooLarge');chunks.push(value);}
  }finally{await reader.cancel();}
  const bytes=new Uint8Array(length);let offset=0;
  for(const chunk of chunks){bytes.set(chunk,offset);offset+=chunk.length;}
  if(mime==='image/svg+xml')checkSVG(new TextDecoder().decode(bytes));
  return `data:${mime};base64,${base64(bytes)}`;
}
async function savedWorks(cache){
  const works=[];
  for(const key of await cache.keys()){
    const response=await cache.match(key);
    works.push({id:new URL(key.url).pathname.split('/').pop(),name:response.headers.get('x-neko-name')?decodeURIComponent(response.headers.get('x-neko-name')):'',bytes:Number(response.headers.get('x-neko-bytes'))});
  }
  return works;
}
async function saveProject(project,cache){
  if(!project?.scenes?.scenesDict||!project?.actors?.actorsDict)throw Error('offlineSaveFailed');
  // Preserve K4 provenance and the original canonical work verbatim. Published
  // K4 reimport rejects resource edits, so media replacements are a sidecar
  // applied only after the current runtime has revalidated the original work.
  const assets={image:Object.create(null),audio:Object.create(null),video:Object.create(null)};
  const json=()=>JSON.stringify({project,assets});
  let size=encoder.encode(json()).length;
  if(size>maxProject)throw Error('offlineTooLarge');
  const resources=new Map(),deadline=Date.now()+120000;
  // Only canonical resource tables are fetched. Script strings and metadata
  // (including K4 provenance) are inert project data, never download targets.
  for(const [kind,table]of [['image',project.styles?.stylesDict],['audio',project.audios?.audiosDict],['video',project.videos?.videosDict]]){
    for(const [id,resource]of Object.entries(table||{})){
      if(Date.now()>=deadline)throw Error('offlineSaveFailed');
      const source=resource.url||resource.cdn_url;
      if(typeof source!=='string'||!source)throw Error('offlineUnsafeAsset');
      const key=`${kind}:${source}`;
      if(!resources.has(key))resources.set(key,await readAsset(source,kind,deadline));
      const embedded=resources.get(key);
      size+=encoder.encode(embedded).length;
      if(size>maxProject)throw Error('offlineTooLarge');
      assets[kind][id]=embedded;
    }
  }
  const body=json(),bytes=encoder.encode(body).length,works=await savedWorks(cache);
  if(Date.now()>=deadline)throw Error('offlineSaveFailed');
  if(bytes>maxProject||works.length>=maxWorks||works.reduce((sum,work)=>sum+work.bytes,bytes)>maxLibrary)throw Error('offlineTooLarge');
  const id=crypto.randomUUID(),name=Array.from(String(project.projectName||'').toWellFormed()).slice(0,160).join('');
  await cache.put(new URL(`offline-projects/${id}`,scope).href,new Response(body,{headers:{'Content-Type':'application/json','x-neko-name':encodeURIComponent(name),'x-neko-bytes':String(bytes)}}));
  return savedWorks(cache);
}
self.addEventListener('message',event=>{
  if(!event.ports[0]||event.data?.type!=='nekoc-offline')return;
  event.waitUntil((async()=>{
    // A same-origin page outside this player cannot read the offline library.
    const client=event.source&&await self.clients.get(event.source.id);
    if(!client||new URL(client.url).origin!==new URL(entry).origin||new URL(client.url).pathname!==new URL(entry).pathname)return;
    const port=event.ports[0],{action,project,id}=event.data;
    const operation=async()=>{
      const cache=await caches.open(projectName);
      if(action==='list')return savedWorks(cache);
      if(action==='save')return saveProject(project,cache);
      if(action==='clear'){await caches.delete(projectName);return [];}
      if(action==='open'&&/^[a-f0-9-]{36}$/.test(id)){
        const response=await cache.match(new URL(`offline-projects/${id}`,scope).href);
        if(response)return response.json();
      }
      throw Error('offlineSaveFailed');
    };
    const result=writes.then(operation);writes=result.catch(()=>{});
    try{port.postMessage({value:await result});}catch(error){port.postMessage({error:error.message});}
  })());
});
